#include <vector>
#include <CGAL/Regular_triangulation_3.h>

using K = CGAL::Exact_predicates_inexact_constructions_kernel;
using RT = CGAL::Regular_triangulation_3<K>;
using Point = RT::Bare_point;

template <typename Point, typename Info>
struct Mesh {
 std::vector<Point> vertices;
 std::vector<unsigned> data;
 std::vector<unsigned> sizes;
 std::vector<Info> info;
 void push_back(std::vector<unsigned> const &vertices, Info const &i);
};

Mesh<Point, double> power_diagram_faces(RT const &rt, double threshold) {
 Mesh<Point, double> mesh;
 std::vector<Point> face_vertices;
 std::vector<unsigned> face_indices;

 for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
 RT::Edge e = *eit;
 double length = rt.segment(e).squared_length();
 if (length < threshold) continue;

 // Collect incident cells (vertices of the dual power diagram face)
 face_vertices.clear();
 face_indices.clear();

 // Get the two cells incident to the edge
 RT::Cell_handle c1 = e.first;
 int idx1 = e.second;
 RT::Cell_handle c2 = c1->neighbor(idx1);

 // Get the vertices of the dual face (power diagram face)
 // The dual face is the Voronoi face dual to the edge
 // It is the intersection of the Voronoi cells of the edge's vertices
 // For power diagrams, this is the set of weighted points whose cells are incident to the edge
 // Here, we collect the vertices of the two incident cells
 for (int i = 0; i < 4; ++i) {
 if (i == idx1) continue;
 face_vertices.push_back(c1->vertex(i)->point().point());
 }

 for (int i = 0; i < 4; ++i) {
 if (c2->neighbor(i) == c1) continue;
 face_vertices.push_back(c2->vertex(i)->point().point());
 }

 // Remove duplicates (simplistic approach)
 // In practice, you may need a more robust deduplication
 std::vector<Point> unique_vertices;
 std::vector<unsigned> unique_indices;
 for (size_t i = 0; i < face_vertices.size(); ++i) {
 bool found = false;
 for (size_t j = 0; j < unique_vertices.size(); ++j) {
 if (unique_vertices[j] == face_vertices[i]) {
 unique_indices.push_back(j);
 found = true;
 break;
 }
 }
 if (!found) {
 unique_indices.push_back(unique_vertices.size());
 unique_vertices.push_back(face_vertices[i]);
 }
 }

 // Add the face to the mesh
 if (!unique_vertices.empty()) {
 unsigned vertex_offset = mesh.vertices.size();
 mesh.vertices.insert(mesh.vertices.end(), unique_vertices.begin(), unique_vertices.end());
 for (unsigned idx : unique_indices) {
 mesh.data.push_back(vertex_offset + idx);
 }
 mesh.sizes.push_back(unique_indices.size());
 mesh.info.push_back(std::sqrt(length));
 }
 }

 return mesh;
}

